mapper.select:
select gbr.route_nm ,st_station.station_nm as st_station_nm ,ed_station.station_nm as ed_station_nm ,st_station.station_id as st_station_id ,ed_station.station_id as ed_station_id ,SUM(MBRLA.TRSFR_CNT) as TRSFR_CNT ,SUM(MBRLA.PSGR_CNT) as PSGR_CNT ,SUM(MBRLA.BUS_USER_CNT) as BUS_USER_CNT ,cgsl.link_id ,ST_ASGEOJSON(ST_LINEMERGE(cgsl.GEOMETRY)) AS GEOJSON ,cgsl.ROAD_NAME from bigdata.ext_ggbis_busroute_infounit gbi inner join bigdata.ext_ggbis_bus_route gbr on gbi.route_id = gbr.route_id inner join bigdata.ext_ggbis_bus_section gbs on gbi.section_id = gbs.section_id left outer join bigdata.ext_ggbis_bus_station st_station on gbs.st_sta_id = st_station.station_id left outer join bigdata.ext_ggbis_bus_station ed_station on gbs.ed_sta_id = ed_station.station_id inner join bigdata.ext_ggbis_link_mapping glm on gbi.link_id = glm.link_id inner join c_gm_std_link cgsl on glm.st_link_id = cgsl.link_id left join mrt_bus_rung_log_anal mbrla on gbs.st_sta_id = mbrla.ride_bstp_id and gbs.ed_sta_id = mbrla.lndi_bstp_id WHERE GBI.ROUTE_ID = #{routeId}
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') BETWEEN '2' AND '6'
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') = '1' OR TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') = '7'
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
GROUP BY ST_STATION.STATION_NM,ED_STATION.STATION_NM,ST_STATION.STATION_ID ,ED_STATION.STATION_ID,CGSL.LINK_ID, GEOJSON,CGSL.ROAD_NAME,UNIT_ORDER ORDER BY UNIT_ORDER ASC

select EGBS.ROUTE_ID ,EGBS.STATION_ID ,EGBS.STA_ORDER ,EGBS.USE_YN ,EGBS.NEAR_STA_CNT ,EGBS.MAIN_STA_YN ,EGBS.COORD_X ,EGBS.COORD_Y ,EGBS.BUS_DIRECTION ,EGBS.BUS_DISTANCE ,EGBS.GIS_LENGTH ,EGBS.SUM_LENGTH ,EGBS.LINK_ORDER ,EGBS.GOWAY_TP ,EGBS.SERVICE_CNT ,EGBS.DIRECTION_DESC ,EGBS.STATION_NM ,EGBS.ROUTE_NM ,EGBS.ST_LINK_ID ,EGBS.LINK_ID ,EGBS.DRVEND_YN ,EGBS.DRVEND_TIME ,EGBS.DRVEND_VEH_ID ,EGBS.DRVEND_PLATE_NO ,EGBS.DRVEND_COMPANY_NM ,EGBS.DELAY_YN ,EGBR.ROUTE_NM ,MBRLA.TRSFR_CNT ,MBRLA.PSGR_CNT ,MBRLA.BUS_USER_CNT ,MBRLA.BUS_RUNG_DSTNE ,ST_ASGEOJSON(ST_LINEMERGE(GCIL.GEOMETRY)) AS GEOJSON ,GCIL.ROAD_NAME FROM BIGDATA.EXT_GGBIS_BUSROUTE_STATION EGBS INNER JOIN ( SELECT EGBS.ROUTE_ID, EGBS.STATION_ID AS END_STATION_ID, MAX(EGBS.STA_ORDER) AS END_STA_ORDER, ST_STATION.START_STATION_ID, ST_STATION.START_STA_ORDER FROM BIGDATA.EXT_GGBIS_BUSROUTE_STATION EGBS INNER JOIN ( SELECT ROUTE_ID , STATION_ID AS START_STATION_ID, STA_ORDER AS START_STA_ORDER FROM BIGDATA.EXT_GGBIS_BUSROUTE_STATION EGBS WHERE EGBS.STATION_ID = #{startStationId} GROUP BY ROUTE_ID , STATION_ID, START_STA_ORDER) ST_STATION ON EGBS.ROUTE_ID = ST_STATION.ROUTE_ID AND EGBS.STA_ORDER > ST_STATION.START_STA_ORDER WHERE EGBS.STATION_ID = #{endStationId} GROUP BY EGBS.ROUTE_ID, EGBS.STATION_ID, ST_STATION.START_STATION_ID, ST_STATION.START_STA_ORDER) BUS_ROUTE ON BUS_ROUTE.ROUTE_ID = EGBS.ROUTE_ID AND (BUS_ROUTE.START_STA_ORDER <= EGBS.STA_ORDER AND BUS_ROUTE.END_STA_ORDER >= EGBS.STA_ORDER) INNER JOIN MRT_BUS_RUNG_LOG_ANAL MBRLA ON MBRLA.BUS_ROUTE_ID = EGBS.ROUTE_ID INNER JOIN BIGDATA.EXT_GGBIS_BUS_ROUTE EGBR ON EGBS.ROUTE_ID = EGBR.ROUTE_ID INNER JOIN C_GM_STD_LINK_TMP /*todo :: _TMP 제거*/ GCIL ON EGBS.LINK_ID = GCIL.LINK_ID WHERE 1=1
AND EGBS.ROUTE_ID = #{routeId}
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') BETWEEN '2' AND '6'
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') = '1' OR TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'D') = '7'
AND TO_CHAR(TO_DATE(MBRLA.CLCT_YMD,'YYYYMMDD'), 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
